using dnlib.DotNet;
using dnlib.DotNet.Emit;
using dnSpy.CallGraph.Core;

static class AuditIlCoverage {
    public static int Run(){
        using var module=new ModuleDefUser("AuditIL.dll");new AssemblyDefUser("AuditIL",new Version(1,0)).Modules.Add(module);
        var type=new TypeDefUser("Audit","Methods",module.CorLibTypes.Object.TypeDefOrRef);module.Types.Add(type);
        MethodDef Method(string name,MethodSig? sig=null){var method=new MethodDefUser(name,sig??MethodSig.CreateStatic(module.CorLibTypes.Void),MethodAttributes.Public|MethodAttributes.Static){Body=new CilBody()};type.Methods.Add(method);return method;}
        void Emit(MethodDef method,params Instruction[] instructions){foreach(var instruction in instructions)method.Body.Instructions.Add(instruction);method.Body.UpdateInstructionOffsets();}
        var target=Method("Target");Emit(target,Instruction.Create(OpCodes.Ret));var other=Method("Other");Emit(other,Instruction.Create(OpCodes.Ret));
        int passed=0,failed=0;
        void Assert(string name,bool success){if(success){passed++;Console.WriteLine("PASS IL "+name);}else{failed++;Console.WriteLine("FAIL IL "+name);}}
        CallGraphSlice Graph(MethodDef root)=>CallGraphIndex.BuildReachable(root,new[]{module},16,100,CallGraphFilterOptions.None).Slice;
        void Check(string name,Instruction[] body,bool expected,bool? invalid=null){var root=Method(name);Emit(root,body);var slice=Graph(root);Assert(name,slice.Links.Any(link=>link.Source==root&&link.Target==target)==expected&&(!invalid.HasValue||slice.Diagnostics.Any(note=>note.Kind==GraphDiagnosticKind.InvalidIl)==invalid.Value));}
        Check("ldtoken is not a pointer",new[]{Instruction.Create(OpCodes.Ldtoken,target),Instruction.Create(OpCodes.Calli,target.MethodSig),Instruction.Create(OpCodes.Ret)},false);
        var unmanaged=target.MethodSig.Clone();unmanaged.CallingConvention=CallingConvention.StdCall;
        Check("calling convention mismatch",new[]{Instruction.Create(OpCodes.Ldftn,target),Instruction.Create(OpCodes.Calli,unmanaged),Instruction.Create(OpCodes.Ret)},false);
        Check("underflow stops without fake calls",new[]{Instruction.Create(OpCodes.Pop),Instruction.Create(OpCodes.Call,target),Instruction.Create(OpCodes.Ret)},false,true);
        Check("foreign branch target",new[]{Instruction.Create(OpCodes.Br,Instruction.Create(OpCodes.Nop)),Instruction.Create(OpCodes.Call,target),Instruction.Create(OpCodes.Ret)},false,true);
        Check("invalid switch operand",new[]{Instruction.CreateLdcI4(0),new Instruction(OpCodes.Switch),Instruction.Create(OpCodes.Call,target),Instruction.Create(OpCodes.Ret)},false,true);
        var bad_return=Method("BadReturn");Emit(bad_return,Instruction.CreateLdcI4(1),Instruction.Create(OpCodes.Ret));Assert("return stack checked",Graph(bad_return).Diagnostics.Any(note=>note.Kind==GraphDiagnosticKind.InvalidIl));
        var grow=Method("GrowingStack");var entry=Instruction.Create(OpCodes.Dup);Emit(grow,Instruction.CreateLdcI4(1),entry,Instruction.Create(OpCodes.Br,entry));Assert("stack-growth loop bounded",Graph(grow).Diagnostics.Any(note=>note.Kind==GraphDiagnosticKind.InvalidIl));
        var unsupported=Method("Unsupported");Emit(unsupported,Instruction.Create(OpCodes.Ldc_R8,1.0),Instruction.Create(OpCodes.Ckfinite),Instruction.Create(OpCodes.Pop),Instruction.Create(OpCodes.Ret));Assert("unsupported semantics visible",Graph(unsupported).Diagnostics.Any(note=>note.Kind==GraphDiagnosticKind.UnsupportedInstruction));
        var helper=Method("PreserveStackHelper",MethodSig.CreateStatic(module.CorLibTypes.IntPtr,module.CorLibTypes.IntPtr));Emit(helper,Instruction.Create(OpCodes.Ldftn,target),Instruction.Create(OpCodes.Ldarg_0),Instruction.Create(OpCodes.Calli,MethodSig.CreateStatic(module.CorLibTypes.Int32)),Instruction.Create(OpCodes.Pop),Instruction.Create(OpCodes.Ret));
        var root=Method("UnknownIndirectPreservesStack",MethodSig.CreateStatic(module.CorLibTypes.Void,module.CorLibTypes.IntPtr));Emit(root,Instruction.Create(OpCodes.Ldarg_0),Instruction.Create(OpCodes.Call,helper),Instruction.Create(OpCodes.Calli,target.MethodSig),Instruction.Create(OpCodes.Ret));Assert("unresolved helper calli pops exactly once",Graph(root).Links.Any(link=>link.Source==root&&link.Target==target));
        var field=new FieldDefUser("Pointer",new FieldSig(module.CorLibTypes.IntPtr),FieldAttributes.Static|FieldAttributes.Public);type.Fields.Add(field);
        var setter=Method("Setter");Emit(setter,Instruction.Create(OpCodes.Ldftn,target),Instruction.Create(OpCodes.Stsfld,field),Instruction.Create(OpCodes.Ret));
        var getter=Method("EffectHelper",MethodSig.CreateStatic(module.CorLibTypes.IntPtr));Emit(getter,Instruction.Create(OpCodes.Ldftn,setter),Instruction.Create(OpCodes.Calli,setter.MethodSig),Instruction.Create(OpCodes.Ldsfld,field),Instruction.Create(OpCodes.Ret));
        var effect_root=Method("VoidCalliEffects");Emit(effect_root,Instruction.Create(OpCodes.Call,getter),Instruction.Create(OpCodes.Calli,target.MethodSig),Instruction.Create(OpCodes.Ret));Assert("void helper calli applies writes",Graph(effect_root).Links.Any(link=>link.Source==effect_root&&link.Target==target));
        var integers=new IntegerExpression.Factory();
        Assert("conv.i1 sign extension",integers.Convert(Code.Conv_I1,integers.Constant(255))?.Value==-1);
        Assert("conv.u1 zero extension",integers.Convert(Code.Conv_U1,integers.Constant(-1))?.Value==255);
        Assert("conv.i2 sign extension",integers.Convert(Code.Conv_I2,integers.Constant(65535))?.Value==-1);
        Assert("conv.u2 zero extension",integers.Convert(Code.Conv_U2,integers.Constant(-1))?.Value==65535);
        Assert("conv.i4 truncation",integers.Convert(Code.Conv_I4,integers.Constant(0x100000001,true))?.Value==1);
        Assert("conv.i8 sign extension",integers.Convert(Code.Conv_I8,integers.Constant(-1))?.Value==-1);
        Assert("conv.u8 zero extension",integers.Convert(Code.Conv_U8,integers.Constant(-1))?.Value==uint.MaxValue);
        Assert("64-bit shift mask",integers.Binary(Code.Shl,integers.Constant(1,true),integers.Constant(40))?.Value==1L<<40);
        Assert("32-bit shift mask",integers.Binary(Code.Shl,integers.Constant(1),integers.Constant(40))?.Value==256);
        Assert("symbolic 64-bit conversion width",integers.Convert(Code.Conv_I8,integers.Variable(9))?.BitWidth==64);
        var local_root=Method("InitializedReference");local_root.Body.InitLocals=true;var reference_local=new Local(module.CorLibTypes.Object);local_root.Body.Variables.Add(reference_local);var other_branch=Instruction.Create(OpCodes.Call,other);Emit(local_root,Instruction.Create(OpCodes.Ldloca,reference_local),Instruction.Create(OpCodes.Ldind_Ref),Instruction.Create(OpCodes.Brtrue,other_branch),Instruction.Create(OpCodes.Call,target),Instruction.Create(OpCodes.Ret),other_branch,Instruction.Create(OpCodes.Ret));var reference_slice=Graph(local_root);Assert("initlocals references are null, not allocated objects",reference_slice.Links.Any(link=>link.Target==target)&&!reference_slice.Links.Any(link=>link.Target==other));
        var integer_root=Method("InitializedInteger");integer_root.Body.InitLocals=true;var integer_local=new Local(module.CorLibTypes.Int32);integer_root.Body.Variables.Add(integer_local);var integer_branch=Instruction.Create(OpCodes.Call,other);Emit(integer_root,Instruction.Create(OpCodes.Ldloc,integer_local),Instruction.Create(OpCodes.Brtrue,integer_branch),Instruction.Create(OpCodes.Call,target),Instruction.Create(OpCodes.Ret),integer_branch,Instruction.Create(OpCodes.Ret));var integer_slice=Graph(integer_root);Assert("initlocals integer is zero",integer_slice.Links.Any(link=>link.Target==target)&&!integer_slice.Links.Any(link=>link.Target==other));
        var many=Enumerable.Range(0,100).Select(index=>SymbolicValue.FromMethod(Method("Many"+index))).ToArray();Assert("100 finite targets retained",SymbolicValue.Merge(many).Methods.Count==100);
        var overflow=Enumerable.Range(0,600).Select(index=>SymbolicValue.FromMethod(Method("Overflow"+index))).ToArray();var capped=SymbolicValue.Merge(overflow);Assert("target cap keeps known candidates and marks remainder",capped.Methods.Count==512&&capped.MayHaveUnknownTargets&&capped.UnknownReason is not null);
        var aggregate=SymbolicValue.FromObject("Tuple",new object()).WithMember("Item2",SymbolicValue.FromMethod(target));var partial=SymbolicValue.Merge(new[]{aggregate,SymbolicValue.Unknown});Assert("unknown aggregate branch does not produce exact field",partial.Members["Item2"].Methods.Contains(target)&&partial.Members["Item2"].MayHaveUnknownTargets);
        var vararg=Method("VarArg",new MethodSig(CallingConvention.VarArg,0,module.CorLibTypes.Void));Emit(vararg,Instruction.Create(OpCodes.Ret));var vararg_signature=vararg.MethodSig.Clone();vararg_signature.ParamsAfterSentinel=new List<TypeSig>{module.CorLibTypes.Int32};var vararg_root=Method("VarArgRoot");Emit(vararg_root,Instruction.CreateLdcI4(5),Instruction.Create(OpCodes.Ldftn,vararg),Instruction.Create(OpCodes.Calli,vararg_signature),Instruction.Create(OpCodes.Ret));var vararg_slice=Graph(vararg_root);Assert("vararg optional arguments consumed",vararg_slice.Links.Any(link=>link.Target==vararg)&&!vararg_slice.Diagnostics.Any(note=>note.Kind==GraphDiagnosticKind.InvalidIl));
        var memory=new FlowMemory(new PointerFlowCatalog(),_=>SymbolicValue.Unknown,integers);var state=new SymbolicState();var address=new object();state.Stack.Add(SymbolicValue.FromStorage(address));state.Stack.Add(SymbolicValue.FromInteger(integers.Constant(255)));memory.Execute(root,Instruction.Create(OpCodes.Stind_I1),state,Array.Empty<SymbolicValue>());state.Stack.Add(SymbolicValue.FromStorage(address));memory.Execute(root,Instruction.Create(OpCodes.Ldind_U1),state,Array.Empty<SymbolicValue>());Assert("indirect byte storage and unsigned load",state.Stack.Single().Integer?.Value==255);
        var fake_type=new TypeDefUser("System","Delegate",module.CorLibTypes.Object.TypeDefOrRef);module.Types.Add(fake_type);var fake_method=new MethodDefUser("Combine",MethodSig.CreateStatic(module.CorLibTypes.Object,module.CorLibTypes.Object,module.CorLibTypes.Object),MethodAttributes.Public|MethodAttributes.Static);fake_type.Methods.Add(fake_method);
        var invocation=new InvocationModel(new[]{module},reference=>reference as MethodDef,(_,_,_)=>SymbolicValue.Unknown);
        Assert("framework-name spoof is not a built-in",!invocation.TryEvaluate(fake_method,new[]{SymbolicValue.FromMethod(target),SymbolicValue.FromMethod(other)},new SymbolicState(),new object(),false,out _));
        var fake_system=new CallGraphFilterOptions(hide_system_methods:true);Assert("System namespace does not hide user methods",fake_system.Includes(target,fake_method));
        var fake_accessor=Method("get_NotAProperty");Assert("get prefix does not hide ordinary methods",new CallGraphFilterOptions(hide_accessors:true).Includes(target,fake_accessor));
        var canceled=new CancellationTokenSource();canceled.Cancel();bool canceled_ok=false;try{CallGraphIndex.Build(module).Select(root,CallGraphDirection.Both,99,500,null,canceled.Token);}catch(OperationCanceledException){canceled_ok=true;}Assert("Both traversal cancellation",canceled_ok);
        var base_type=new TypeDefUser("Audit","Base",module.CorLibTypes.Object.TypeDefOrRef);module.Types.Add(base_type);var derived=new TypeDefUser("Audit","Derived",base_type);module.Types.Add(derived);
        var base_run=new MethodDefUser("Run",MethodSig.CreateInstance(module.CorLibTypes.Void),MethodAttributes.Public|MethodAttributes.Virtual|MethodAttributes.NewSlot){Body=new CilBody()};base_type.Methods.Add(base_run);Emit(base_run,Instruction.Create(OpCodes.Call,other),Instruction.Create(OpCodes.Ret));
        var override_run=new MethodDefUser("Run",MethodSig.CreateInstance(module.CorLibTypes.Void),MethodAttributes.Public|MethodAttributes.Virtual){Body=new CilBody()};derived.Methods.Add(override_run);Emit(override_run,Instruction.Create(OpCodes.Call,target),Instruction.Create(OpCodes.Ret));
        var ctor=new MethodDefUser(".ctor",MethodSig.CreateInstance(module.CorLibTypes.Void),MethodAttributes.Public|MethodAttributes.SpecialName|MethodAttributes.RTSpecialName){Body=new CilBody()};derived.Methods.Add(ctor);Emit(ctor,Instruction.Create(OpCodes.Ret));
        var virtual_root=Method("VirtualIndexRoot");Emit(virtual_root,Instruction.Create(OpCodes.Newobj,ctor),Instruction.Create(OpCodes.Callvirt,base_run),Instruction.Create(OpCodes.Ret));var virtual_index=CallGraphIndex.Build(module);Assert("reverse index does not retain superseded base target",virtual_index.Outgoing(virtual_root).Any(link=>link.Target==override_run)&&!virtual_index.Outgoing(virtual_root).Any(link=>link.Target==base_run));
        var costly=Method("CostlyHelper");for(int instruction=0;instruction<18000;instruction++)costly.Body.Instructions.Add(Instruction.Create(OpCodes.Nop));Emit(costly,Instruction.Create(OpCodes.Ret));
        var budget_parent=Method("CallsAfterCostlyHelpers");Emit(budget_parent,Instruction.Create(OpCodes.Call,costly),Instruction.Create(OpCodes.Call,costly),Instruction.Create(OpCodes.Call,costly),Instruction.Create(OpCodes.Call,target),Instruction.Create(OpCodes.Ret));var parent_graph=Graph(budget_parent);Assert("helper work cannot truncate parent direct calls",parent_graph.Links.Any(link=>link.Source==budget_parent&&link.Target==target)&&!parent_graph.Diagnostics.Any(note=>note.Method==budget_parent&&note.Kind==GraphDiagnosticKind.AnalysisBudget));
        var no_summary=new ReachableCallAnalysis(new[]{module},CancellationToken.None);typeof(ReachableCallAnalysis).GetField("remaining_helper_steps",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.SetValue(no_summary,0);var no_summary_graph=no_summary.Select(budget_parent,16,100,CallGraphFilterOptions.None);Assert("no helper budget still discovers direct calls",no_summary_graph.Links.Any(link=>link.Source==budget_parent&&link.Target==target));
        var structural=Method("StructuralRecovery");var dead=Instruction.Create(OpCodes.Call,other);Emit(structural,Instruction.CreateLdcI4(0),Instruction.Create(OpCodes.Brtrue,dead),Instruction.Create(OpCodes.Ldftn,other),Instruction.Create(OpCodes.Pop),Instruction.Create(OpCodes.Call,target),Instruction.Create(OpCodes.Ret),dead,Instruction.Create(OpCodes.Ret));var no_flow=new ReachableCallAnalysis(new[]{module},CancellationToken.None);typeof(ReachableCallAnalysis).GetField("remaining_steps",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.SetValue(no_flow,0);var structural_graph=no_flow.Select(structural,16,100,CallGraphFilterOptions.None);Assert("structural recovery keeps real call not address or dead branch",structural_graph.Links.Any(link=>link.Source==structural&&link.Target==target&&link.IsPotential)&&!structural_graph.Links.Any(link=>link.Target==other));Assert("structural recovery reports incomplete value flow",structural_graph.Diagnostics.Any(note=>note.Detail.Contains("structurally reachable",StringComparison.Ordinal)));
        Console.WriteLine($"audit_il_passed={passed} failed={failed}");return failed==0?0:1;
    }
}
